cat > /etc/nginx/nginx.conf << 'EOF'
user www-data;
worker_processes auto;
pid /run/nginx.pid;
include /etc/nginx/modules-enabled/*.conf;

events {
    worker_connections 1024;
}

http {
    sendfile on;
    tcp_nopush on;
    tcp_nodelay on;
    types_hash 2048;
    server_tokens off;
    keepalive_timeout 65;

    include /etc/nginx/mime.types;
    default_type application/octet-stream;

    # Detailed benchmark log format: timestamp, method, status, user agent
    log_format benchmark '$time_local | $request_method | $status | "$http_user_agent"';

    access_log /var/log/nginx/benchmark-access.log benchmark;
    error_log /var/log/nginx/benchmark-error.log warn;

    # Rate limiting: 10 requests/sec per IP with 10MB shared memory zone
    limit_req_zone $binary_remote_addr zone=req_limit:10m rate=10r/s;
    limit_req_status 429;

    gzip on;

    include /etc/nginx/conf.d/*.conf;
    include /etc/nginx/sites-enabled/*;
}
EOF

cat > /etc/nginx/conf.d/benchmark-site.conf << 'EOF'
# Benchmark webserver: static files on port 8080 with rate limiting and
# detailed request logging.
server {
    listen 8080;
    server_name _;

    root /var/www/html;
    index index.html index.htm;

    # Detailed request logging (timestamp, method, status, user agent)
    access_log /var/log/nginx/benchmark-access.log benchmark;
    error_log /var/log/nginx/benchmark-error.log warn;

    # Apply the rate limit defined in nginx.conf (10r/s, burst 10)
    limit_req zone=req_limit burst=10 nodelay;

    # Custom 404 error page
    error_page 404 /404.html;

    location / {
        try_files $uri $uri/ =404;
    }
}
EOF

